@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h3>Notepad</h3>

<textarea @bind="content" @bind:event="oninput" rows="12" style="width:100%;" />

<div style="margin-top:0.5rem; display:flex; gap:0.5rem; align-items:center;">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-danger" @onclick="Clear">Clear</button>
    @if (lastSaved is not null)
    {
        <span>Last saved at @lastSaved.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSaved;
    private System.Threading.Timer? autoSaveTimer;
    private IJSObjectReference? module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/Notepad.razor.js");

            var restored = await module.InvokeAsync<string?>("load");
            if (!string.IsNullOrEmpty(restored))
            {
                content = restored;
                savedContent = restored;
                StateHasChanged();
            }

            autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSave), null,
                TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private bool HasUnsavedChanges => content != savedContent;

    private async Task AutoSave()
    {
        if (HasUnsavedChanges)
        {
            await PersistContent();
            StateHasChanged();
        }
    }

    private async Task SaveNow()
    {
        await PersistContent();
    }

    private async Task PersistContent()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("save", content);
            savedContent = content;
            lastSaved = DateTime.Now;
            await module.InvokeVoidAsync("setDirty", false);
        }
    }

    private async Task Clear()
    {
        content = string.Empty;
        savedContent = string.Empty;
        lastSaved = null;
        if (module is not null)
        {
            await module.InvokeVoidAsync("clear");
            await module.InvokeVoidAsync("setDirty", false);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender, bool _) => await Task.CompletedTask;

    // Keep beforeunload in sync with dirty state
    private async Task UpdateDirtyFlag()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("setDirty", HasUnsavedChanges);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }
        if (module is not null)
        {
            await module.InvokeVoidAsync("setDirty", false);
            await module.DisposeAsync();
        }
    }
}

